def build_rag_prompt(query: str, documents: list[str], max_chars: int = 1000) -> str:
    context_parts = []
    current_length = 0
    for doc in documents:
        if current_length + len(doc) + 1 > max_chars:
            break
        context_parts.append(doc)
        current_length += len(doc) + 1
    joined_context = '\n'.join(context_parts)
    return f'Context:\n{joined_context}\n\nQuery: {query}\nAnswer strictly based on the context above.'
